def _load(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise Invalid('input exceeds byte bound')
    try:
        text = raw.decode('utf-8')
    except (UnicodeDecodeError, ValueError):
        raise Invalid('malformed utf-8')
    try:
        return json.loads(text, object_pairs_hook=_pairs,
                          parse_float=_bad_float, parse_constant=_bad_const)
    except Invalid:
        raise
    except Exception:
        raise Invalid('malformed json')


# ------------------------------------------------------------- validators
def _need_int(value):
    if isinstance(value, bool) or not isinstance(value, int):
        raise Invalid('expected an integer')
    return value


def _need_asn(value):
    _need_int(value)
    if value < 1 or value > ASN_MAX:
        raise Invalid('asn out of range')
    return value


def _need_list(value):
    if not isinstance(value, list):
        raise Invalid('expected an array')
    return value


def _need_fields(rec, names):
    if not isinstance(rec, dict) or set(rec.keys()) != names:
        raise Invalid('unexpected record fields')
    return rec


def _canon(a, b):
    return (a, b) if a < b else (b, a)


